package com.corusoft.bareo.bareobackend.shared.utils.mapper;

import java.util.function.Function;

public class ResponseMapperUtils {

  /**
   * Returns the given {@code value} if not null, else return the value generated by the function
   * {@code getter}.
   *
   * @param value Value to return. May be null
   * @param getter Function that generates the value to return
   * @param <T> Value type
   * @param <R> Return type of the getter
   */
  public static <T, R> R nullable(T value, Function<T, R> getter) {
    return (value != null) ? getter.apply(value) : null;
  }
}
